import { describe, expect, it } from 'vitest';
import { validateCourse } from './Course';
import { createCourseBuilder } from './CourseBuilder';
import { validateHole } from './Hole';
import { createHoleBuilder } from './HoleBuilder';
import { greenHillsCourse } from './data/green-hills';

const v = (x: number, y: number, z: number) => ({ x, y, z });

/** Exercises every level builder method from the design doc in one hole. */
function lab() {
  return createHoleBuilder({ id: 'lab-01', name: 'Builder Lab', par: 4, spawn: v(0, 0.4, 0) })
    .addFloor({ id: 'fairway', position: v(0, 0, 10), size: v(8, 0.4, 22) })
    .addRamp({ id: 'ramp', position: v(0, 0.7, 16), size: v(6, 1.2, 4), material: 'stone' })
    .addCurve({ id: 'bend', center: v(6, 0, 24), radius: 6, width: 5, startAngle: Math.PI, sweepAngle: -Math.PI / 2, segments: 4 })
    .addWall({ id: 'rail', position: v(-4.2, 0.7, 10), size: v(0.4, 1.4, 22), restitution: 0.4 })
    .addBumper({ id: 'bumper', position: v(1.5, 0.5, 8) })
    .addObstacle({ id: 'pillar', type: 'pillar', transform: { position: v(-1.5, 0.9, 12) }, size: v(1, 1.8, 1) })
    .addSpinner({ id: 'spinner', position: v(0, 1, 18), speed: 1.6 })
    .addMovingPlatform({ id: 'platform', position: v(0, 0.3, 21), size: v(2.4, 0.35, 4), distance: 2.5 })
    .addTeleporter({ id: 'portal', position: v(-3, 0.4, 14), size: v(1.6, 1, 1.6), exitPosition: v(3, 0.4, 20), exitVelocityScale: 0.5 })
    .addFan({ id: 'fan', position: v(0, 0.8, 13), size: v(4, 1.6, 4), direction: v(0, 0, 1), maxForce: 6 })
    .addWater({ id: 'pond', position: v(4, 0.1, 19), size: v(3, 0.4, 3) })
    .addKillZone({ id: 'pit', position: v(0, -1, 25), size: v(10, 1, 4), penaltyStrokes: 2 })
    .addHole({ position: v(6, 0.12, 30) });
}

describe('HoleBuilder', () => {
  it('builds a valid hole descriptor', () => {
    const hole = lab().buildHole();
    expect(() => validateHole(hole)).not.toThrow();
    expect(hole.id).toBe('lab-01');
    expect(hole.par).toBe(4);
    expect(hole.cup).toEqual({ position: v(6, 0.12, 30), radius: 0.32, captureDepth: 0.3 });
    expect(hole.surfaces).toHaveLength(6);
    expect(hole.obstacles.map((o) => o.type)).toEqual([
      'wall',
      'bumper',
      'pillar',
      'spinner',
      'platform',
      'water',
      'void',
    ]);
  });

  it('lays curve segments along the arc', () => {
    const segments = lab().buildHole().surfaces.filter((surface) => surface.id.startsWith('bend-'));
    expect(segments).toHaveLength(4);
    for (const segment of segments) {
      const { x, z } = segment.transform.position;
      expect(Math.hypot(x - 6, z - 24)).toBeCloseTo(6, 6);
      expect(segment.transform.rotation).toBeDefined();
    }
  });

  it('collects runtime zones and force obstacles next to the descriptor', () => {
    const blueprint = lab().build();
    expect(blueprint.zones.map((zone) => zone.type)).toEqual(['water', 'kill']);

    const pit = blueprint.zones.find((zone) => zone.id === 'pit');
    expect(pit?.penaltyStrokes).toBe(2);
    expect(pit?.bounds).toEqual({ min: v(-5, -1.5, 23), max: v(5, -0.5, 27) });

    const portal = blueprint.forceObstacles.find((config) => config.kind === 'teleporter');
    expect(portal).toBeDefined();
    if (portal?.kind === 'teleporter') {
      expect(portal.exitPosition).toEqual(v(3, 0.4, 20));
      expect(portal.exitVelocityScale).toBe(0.5);
      expect(portal.entryZone).toEqual({ shape: 'box', center: v(-3, 0.4, 14), halfExtents: v(0.8, 0.5, 0.8) });
    }

    const fan = blueprint.forceObstacles.find((config) => config.kind === 'fan');
    expect(fan?.kind === 'fan' ? fan.maxForce : 0).toBe(6);
  });

  it('derives bounds around the placed geometry', () => {
    const bounds = lab().buildHole().bounds;
    expect(bounds.min.x).toBeLessThanOrEqual(-6.4);
    expect(bounds.max.z).toBeGreaterThanOrEqual(32);
    expect(bounds.min.y).toBeLessThan(bounds.max.y);
  });

  it('generates ids and rejects duplicates', () => {
    const hole = createHoleBuilder({ id: 'auto-01', name: 'Auto', par: 3, spawn: v(0, 0.4, 0) })
      .addFloor({ position: v(0, 0, 5), size: v(6, 0.4, 12) })
      .addWall({ position: v(-3, 0.7, 5), size: v(0.4, 1.4, 12) })
      .addHole({ position: v(0, 0.12, 9) })
      .buildHole();
    expect(hole.surfaces.map((surface) => surface.id)).toEqual(['floor-1']);
    expect(hole.obstacles.map((obstacle) => obstacle.id)).toEqual(['wall-2']);

    expect(() =>
      createHoleBuilder({ id: 'dup-01', name: 'Dup', par: 3, spawn: v(0, 0.4, 0) })
        .addFloor({ id: 'same', position: v(0, 0, 5), size: v(6, 0.4, 12) })
        .addWall({ id: 'same', position: v(0, 0.7, 5), size: v(0.4, 1.4, 12) }),
    ).toThrow(/duplicate element id/);
  });

  it('requires a cup before building', () => {
    expect(() =>
      createHoleBuilder({ id: 'nocup-01', name: 'No Cup', par: 3, spawn: v(0, 0.4, 0) })
        .addFloor({ position: v(0, 0, 5), size: v(6, 0.4, 12) })
        .buildHole(),
    ).toThrow(/cup/);
  });
});

describe('CourseBuilder.addHoleWith', () => {
  it('appends a builder-authored hole to a course', () => {
    const course = createCourseBuilder({ id: 'mini', name: 'Mini', themeId: 'mini' })
      .addHoleWith({ id: 'mini-01', name: 'Opener', par: 3, spawn: v(0, 0.4, 0) }, (hole) => {
        hole.addFloor({ id: 'fairway', position: v(0, 0, 6), size: v(6, 0.4, 14) });
        hole.addHole({ position: v(0, 0.12, 11) });
      })
      .build();
    expect(course.holes).toHaveLength(1);
    expect(course.holes[0]?.surfaces[0]?.id).toBe('fairway');
  });
});

describe('green-hills course', () => {
  it('still validates after moving to the hole builder', () => {
    expect(() => validateCourse(greenHillsCourse)).not.toThrow();
    expect(greenHillsCourse.holes).toHaveLength(9);
  });

  it('keeps the authored geometry', () => {
    const first = greenHillsCourse.holes[0];
    expect(first?.id).toBe('gh-01-meadow-line');
    expect(first?.surfaces.map((surface) => surface.id)).toEqual(['fairway']);
    expect(first?.obstacles.map((obstacle) => obstacle.id)).toEqual(['left-rail', 'right-rail']);
    expect(first?.bounds).toEqual({ min: v(-6, -4, -2), max: v(6, 8, 16) });

    const last = greenHillsCourse.holes[8];
    expect(last?.obstacles.map((obstacle) => obstacle.id)).toEqual(['left-drop', 'right-drop', 'spinner-a', 'gate-b']);
    expect(last?.cup.position).toEqual(v(0, 2.05, 27));
  });
});
