import { readFileSync, writeFileSync } from 'node:fs';

const path = 'src/courses/CourseBuilder.ts';
let source = readFileSync(path, 'utf8');

const importAnchor = "import { defineCourse } from './Course';";
if (!source.includes(importAnchor)) throw new Error('import anchor not found');
if (!source.includes('HoleBuilder')) {
  source = source.replace(
    importAnchor,
    importAnchor + "\nimport { createHoleBuilder, type HoleBuilder, type HoleBuilderOptions } from './HoleBuilder';",
  );
}

const buildAnchor = '  build(): Course {';
if (!source.includes(buildAnchor)) throw new Error('build anchor not found');
if (!source.includes('addHoleWith')) {
  const method = [
    '  /** Builds a hole through the level builder API and appends it to the course. */',
    '  addHoleWith(options: HoleBuilderOptions, configure: (builder: HoleBuilder) => void): this {',
    '    const builder = createHoleBuilder(options);',
    '    configure(builder);',
    '    return this.addHole(builder.buildHole());',
    '  }',
    '',
    '',
  ].join('\n');
  source = source.replace(buildAnchor, method + buildAnchor);
}

writeFileSync(path, source);
console.log('CourseBuilder patched');
